import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.XctAhZuT.js";const u=JSON.parse('{"title":"配置 AI","description":"AI 不是核心学习流程的前置条件。未配置模型时，课程、复习、错题和本地课程检索继续可用。","frontmatter":{"description":"AI 不是核心学习流程的前置条件。未配置模型时，课程、复习、错题和本地课程检索继续可用。"},"headers":[],"relativePath":"guide/ai-configuration.md","filePath":"guide/ai-configuration.md","lastUpdated":1790697640000}'),r={name:"guide/ai-configuration.md"};function i(l,t,n,s,h,c){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="配置-ai" tabindex="-1">配置 AI <a class="header-anchor" href="#配置-ai" aria-label="Permalink to &quot;配置 AI&quot;">​</a></h1><p>AI 不是核心学习流程的前置条件。未配置模型时，课程、复习、错题和本地课程检索继续可用。</p><h2 id="配置项" tabindex="-1">配置项 <a class="header-anchor" href="#配置项" aria-label="Permalink to &quot;配置项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td>Provider preset</td><td>服务商预设或「自定义」</td></tr><tr><td>Base URL</td><td>API 根地址（自定义时手填；命名预设自动带入）</td></tr><tr><td>API key</td><td>服务凭据</td></tr><tr><td>Chat model</td><td>流式对话与解释模型；留空回退预设默认模型</td></tr><tr><td>JSON model</td><td>结构化生成模型；留空回退预设默认模型</td></tr><tr><td>Strict schema mode</td><td><code>auto</code>（默认，遇 400 回退 <code>json_object</code>）/ <code>on</code> / <code>off</code></td></tr><tr><td>Reasoning</td><td>显式开关（<code>reasoning_effort</code> / <code>thinking</code> 字段）；预设的 <code>supportsReasoning</code> 只是能力提示，不会自动开</td></tr><tr><td>响应缓存</td><td>命中相同请求时直接复用结果</td></tr></tbody></table><p>内置预设：<strong>DeepSeek</strong>（默认 <code>deepseek-v4-flash</code>）、<strong>Kimi</strong>（<code>kimi-k3</code>）、<strong>Qwen</strong>（<code>qwen3.8-max</code>）、<strong>MiMo</strong>（<code>mimo-v2.5-pro</code>）、<strong>自定义</strong>。具体模型名由用户配置，文档不假设远端默认值长期有效。</p><h2 id="配置顺序" tabindex="-1">配置顺序 <a class="header-anchor" href="#配置顺序" aria-label="Permalink to &quot;配置顺序&quot;">​</a></h2><ol><li>打开「设置 → 高级 → AI 连接」。</li><li>选择 provider preset（命名预设自动填入 Base URL 与默认模型；「自定义」保留你手填的值）。</li><li>输入 API key；自定义服务可填本地或自托管 endpoint。</li><li>需要分流时分别选择 Chat model 与 JSON model。</li><li>执行连接测试。</li><li>检查延迟和错误信息。</li><li>保存后从 AI Hub 发起最小文本请求。</li></ol><h2 id="连接测试" tabindex="-1">连接测试 <a class="header-anchor" href="#连接测试" aria-label="Permalink to &quot;连接测试&quot;">​</a></h2><p>连接测试只证明当前 endpoint、凭据和最小请求可达，不证明所有结构化生成功能都受支持。JSON schema 不受支持时，引擎可按配置回退到 JSON object；结果仍需本地解析和校验。</p><h2 id="密钥存储" tabindex="-1">密钥存储 <a class="header-anchor" href="#密钥存储" aria-label="Permalink to &quot;密钥存储&quot;">​</a></h2><p>原生平台使用可用的安全存储实现。Web 或缺少安全存储插件的平台仅在会话内持有凭据，并在界面中显示限制。</p><p>密钥不得进入：</p><ul><li>普通日志。</li><li>Prompt 缓存键。</li><li>脱敏报告。</li><li>课程 JSON。</li><li>文档或截图。</li></ul><h2 id="超时、重试与取消" tabindex="-1">超时、重试与取消 <a class="header-anchor" href="#超时、重试与取消" aria-label="Permalink to &quot;超时、重试与取消&quot;">​</a></h2><p>请求体包含 model、messages、temperature，以及可选的 max_tokens、reasoning_effort 与 response_format。请求有超时上限（120 秒）与取消令牌；取消是协作式操作：客户端停止接收和处理结果，不保证远端立即停止计费。</p><h2 id="预算" tabindex="-1">预算 <a class="header-anchor" href="#预算" aria-label="Permalink to &quot;预算&quot;">​</a></h2><p>当前<strong>没有</strong>用量与花费管控。引擎未实现预算管理器，AI 侧不提供每日软/硬限制、Token 计数或成本估算，供应商定价表也未内置。因此不要在文档或预期里假设存在「预算上限」开关；花费需在服务商侧自行查看。</p><h2 id="故障判定" tabindex="-1">故障判定 <a class="header-anchor" href="#故障判定" aria-label="Permalink to &quot;故障判定&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误</th><th>处理</th></tr></thead><tbody><tr><td>401 / 403</td><td>检查 key、权限和 base URL</td></tr><tr><td>模型不存在</td><td>检查模型名与 endpoint</td></tr><tr><td>schema 不支持</td><td>允许受控回退或更换 JSON model</td></tr><tr><td>超时</td><td>降低输入规模、检查网络或本地服务</td></tr><tr><td>输出不可解析</td><td>保留原始错误状态，不直接写入课程</td></tr></tbody></table><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/ai">AI 伴学</a></li><li><a href="/docs/guide/ai-workflows">AI 工作流</a></li><li><a href="/docs/guide/data-and-privacy">本地数据与隐私</a></li></ul>',21)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
